#!/bin/bash
# Scarica i video e i media del pacchetto (serve la connessione UNA volta). Riavviabile: salta i file già presenti.
cd "$(dirname "$0")" || exit 1
mkdir -p video media
R="https://www.alessandromilia.it/"
ok=0; ko=0
dl(){ [ -s "$2" ] && { echo "  già presente: $2"; return; }; echo "  scarico $2"; if curl -fsSL -e "$R" -o "$2.part" "$1"; then mv "$2.part" "$2"; ok=$((ok+1)); else rm -f "$2.part"; echo "  ✗ non scaricato: $1"; ko=$((ko+1)); fi; }
cc(){ [ -s "$2" ] && return; curl -fsSL -e "$R" -o "$2" "$1" 2>/dev/null || rm -f "$2"; }
echo "Video: 24"
